"},{"path":"public/recover.html","content":"<!doctype html>
<html lang="zh-CN">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width,initial-scale=1" />
    <meta name="theme-color" content="#234e41" />
    <title>TalkSprout · Reload</title>
    <style>
      body {
        max-width: 440px;
        margin: 12vh auto;
        padding: 28px;
        background: #faf9f5;
        color: #234e41;
        font:
          16px/1.8 system-ui,
          sans-serif;
      }
      h1 {
        font-size: 28px;
      }
      button {
        border: 0;
        border-radius: 9px;
        padding: 14px 22px;
        background: #234e41;
        color: white;
        font: inherit;
        cursor: pointer;
      }
    </style>
  </head>
  <body>
    <h1>TalkSprout</h1>
    <p id="message">重新打开应用，收藏和语言设置会保留。</p>
    <button id="reload" type="button">重新打开</button>
    <script>
      (function () {
        var button = document.getElementById("reload");
        var english = !/^zh/i.test(navigator.language || "");
        try {
          var saved = localStorage.getItem("talksprout:locale");
          if (saved) english = saved === "en";
        } catch (_) {}
        if (english) {
          document.documentElement.lang = "en";
          document.getElementById("message").textContent =
            "Reopen the app. Your favorites and language preference will stay saved.";
          button.textContent = "Reopen app";
        }
        button.addEventListener("click", function () {
          button.disabled = true;
          var jobs = [];
          var root = new URL("./", location.href);
          if ("serviceWorker" in navigator)
            jobs.push(
              navigator.serviceWorker
                .getRegistrations()
                .then(function (registrations) {
                  return Promise.all(
                    registrations
                      .filter(function (r) {
                        return r.scope === root.href;
                      })
                      .map(function (r) {
                        return r.unregister();
                      }),
                  );
                }),
            );
          if ("caches" in window)
            jobs.push(
              caches.keys().then(function (keys) {
                return Promise.all(
                  keys
                    .filter(function (key) {
                      return key.indexOf("talksprout-scope-" + encodeURIComponent(root.href) + "-") === 0;
                    })
                    .map(function (key) {
                      return caches.delete(key);
                    }),
                );
              }),
            );
          Promise.all(jobs)
            .catch(function () {})
            .then(function () {
              root.searchParams.set("refresh", String(Date.now()));
              location.replace(root.href);
            });
        });
      })();
    </script>
  </body>
</html>
"},{"path":"src/UpdateBanner.tsx","content":"import type { Locale } from "./types";
import type { AppUpdateSnapshot } from "./app-update";

export function UpdateBanner({
  snapshot,
  completed,
  locale,
  onUpdate,
}: {
  snapshot: AppUpdateSnapshot;
  completed: boolean;
  locale: Locale;
  onUpdate: () => void;
}) {
  const { phase } = snapshot;
  if (phase === "idle" && !completed) return null;
  const s = (zh: string, en: string) => (locale === "en" ? en : zh);
  const busy = phase === "applying" || phase === "reloading";
  const failed = phase === "stalled" || phase === "error";
  const done = phase === "idle" && completed;
  const title = done
    ? s("更新完成", "App updated")
    : busy
      ? s("正在更新…", "Updating…")
      : failed
        ? s("更新暂未完成", "Update not completed")
        : s("新版本已就绪", "An update is ready");
  const description = done
    ? s("已重新打开，可以继续练习。", "Reopened and ready to practice.")
    : busy
      ? s("完成后会自动重新打开。", "The app will reopen automatically.")
      : failed
        ? s(
            "请重试，或关闭 App 后重新打开。",
            "Try again, or close and reopen the app.",
          )
        : s(
            "重新打开即可使用，收藏与语言设置会保留。",
            "Reopen to use it. Saved prompts and language stay.",
          );
  return (
    <div
      id="update-bar"
      className={`app-banner update-banner${failed ? " update-stalled" : ""}`}
      role="status"
      aria-live="polite"
      aria-atomic="true"
    >
      <span
        className={busy ? "update-spinner" : "update-symbol"}
        aria-hidden="true"
      >
        {busy ? "" : done ? "✓" : failed ? "!" : "↻"}
      </span>
      <span className="update-copy">
        <strong>{title}</strong>
        <small>{description}</small>
      </span>
      {!done && (
        <button
          id="update"
          type="button"
          disabled={busy}
          aria-busy={busy}
          onClick={onUpdate}
        >
          {busy
            ? s("请稍候", "Please wait")
            : failed
              ? s("重试更新", "Retry update")
              : s("立即更新", "Update now")}
        </button>
      )}
    </div>
  );
}
"},{"path":"src/app-update.ts","content":"export type AppUpdatePhase =
  | "idle"
  | "available"
  | "applying"
  | "stalled"
  | "error"
  | "reloading";
export interface AppUpdateSnapshot {
  phase: AppUpdatePhase;
}
interface UpdateOptions {
  container: ServiceWorkerContainer;
  onChange: (snapshot: AppUpdateSnapshot) => void;
  reload: () => void;
  onRegistrationError: () => void;
  onRegistration?: (registration: ServiceWorkerRegistration) => void;
}

/** Owns update activation independently of React and the clipboard/toast state. */
export function createAppUpdateManager({
  container,
  onChange,
  reload,
  onRegistrationError,
  onRegistration,
}: UpdateOptions) {
  let registration: ServiceWorkerRegistration | undefined;
  let offered: ServiceWorker | null = null;
  let target: ServiceWorker | null = null;
  let knownController = container.controller;
  let requested = false;
  let refreshing = false;
  let disposed = false;
  let phase: AppUpdatePhase = "idle";
  let timeout: ReturnType<typeof setTimeout> | undefined;
  let poll: ReturnType<typeof setInterval> | undefined;
  const watched = new Set<ServiceWorker>();
  const publish = (next: AppUpdatePhase) => {
    if (disposed || phase === next) return;
    phase = next;
    onChange({ phase });
  };
  const clearWait = () => {
    clearTimeout(timeout);
    clearInterval(poll);
    timeout = undefined;
    poll = undefined;
  };
  const reloadOnce = () => {
    if (disposed || refreshing) return;
    refreshing = true;
    clearWait();
    publish("reloading");
    reload();
  };
  const fail = () => {
    requested = false;
    clearWait();
    publish("error");
  };
  const watch = (worker: ServiceWorker | null) => {
    if (!worker || watched.has(worker)) return;
    watched.add(worker);
    worker.addEventListener("statechange", sync);
  };
  function sync() {
    if (disposed || !registration || refreshing) return;
    watch(registration.installing);
    watch(registration.waiting);
    watch(target);
    if (requested && target) {
      if (target.state === "activated" && registration.active === target) {
        reloadOnce();
        return;
      }
      if (target.state === "redundant") fail();
      // A waiting worker disappears during activation; keep progress visible.
      if (requested) return;
    }
    const waiting = registration.waiting;
    // The first cache install briefly passes through waiting before activating.
    // Offer an update only when it actually replaces another active worker.
    if (
      waiting?.state === "installed" &&
      registration.active &&
      registration.active !== waiting &&
      container.controller !== waiting
    ) {
      offered = waiting;
      if (phase !== "error") publish("available");
    } else if (
      phase === "available" &&
      (offered?.state === "redundant" ||
        (offered?.state === "activated" &&
          knownController === offered &&
          container.controller === offered))
    ) {
      offered = null;
      publish("idle");
    }
  }
  const controllerChanged = () => {
    if (disposed || refreshing) return;
    const current = container.controller;
    if (!current || current === knownController) {
      sync();
      return;
    }
    const firstClaim = !knownController;
    knownController = current;
    // Installing the offline cache for the first time must not interrupt practice.
    if (firstClaim && !requested) {
      sync();
      return;
    }
    // An initial old-worker claim can race with acceptance of a newer worker.
    if (requested && target && current !== target) {
      sync();
      return;
    }
    reloadOnce();
  };
  const recheck = () => {
    if (!disposed) void registration?.update().catch(() => {});
  };
  return {
    async start(scriptURL: string) {
      container.addEventListener("controllerchange", controllerChanged);
      try {
        const reg = await container.register(scriptURL, {
          updateViaCache: "none",
        });
        if (disposed) return;
        registration = reg;
        onRegistration?.(reg);
        reg.addEventListener("updatefound", sync);
        sync();
      } catch {
        if (!disposed) onRegistrationError();
      }
    },
    request() {
      if (disposed || refreshing || phase === "applying") return;
      const fresh = registration?.waiting;
      const candidate = fresh?.state === "installed" ? fresh : offered;
      if (!candidate || candidate.state === "redundant" || !registration) {
        fail();
        recheck();
        return;
      }
      target = candidate;
      requested = true;
      clearWait();
      publish("applying");
      watch(target);
      sync();
      if (refreshing) return;
      if (target.state === "activated") {
        fail();
        recheck();
        return;
      }
      timeout = setTimeout(() => {
        clearWait();
        publish("stalled");
      }, 12000);
      // Some suspended standalone sessions can miss lifecycle notifications.
      // Only reload after the offered version is confirmed active, never on time alone.
      poll = setInterval(sync, 500);
      try {
        if (target.state === "installed") target.postMessage("SKIP_WAITING");
      } catch {
        fail();
      }
    },
    resume(checkForUpdates = true) {
      sync();
      if (checkForUpdates) recheck();
    },
    dispose() {
      disposed = true;
      clearWait();
      container.removeEventListener("controllerchange", controllerChanged);
      registration?.removeEventListener("updatefound", sync);
      for (const worker of watched)
        worker.removeEventListener("statechange", sync);
      watched.clear();
    },
  };
}
"},{"path":"src/offline-check.ts","content":"import type { OfflineStatus } from './offline-readiness';

interface OfflineCheckOptions<Handle> {
  read: () => Promise<OfflineStatus>;
  publish: (status: OfflineStatus) => void;
  visible: () => boolean;
  schedule: (callback: () => void, delay: number) => Handle;
  cancel: (handle: Handle) => void;
}

/** One immediate read and five retries per burst; events can begin a fresh burst. */
export function createOfflineCheck<Handle>(options: OfflineCheckOptions<Handle>) {
  const delays = [2000, 4000, 8000, 16000, 30000];
  let timer: Handle | undefined;
  let active = false;
  let checking = false;
  let disposed = false;
  let generation = 0;
  let retries = 0;
  let pending = false;
  function stop() {
    generation++;
    active = false;
    pending = false;
    if (timer !== undefined) options.cancel(timer);
    timer = undefined;
  }
  async function check() {
    if (disposed || !active || !options.visible()) return;
    if (checking) { pending = true; return; }
    checking = true;
    const current = generation;
    let status: OfflineStatus;
    try { status = await options.read(); } catch { status = 'unavailable'; }
    checking = false;
    if (disposed) return;
    if (current === generation && active && options.visible()) {
      options.publish(status);
      const delay = delays[retries];
      if ((status === 'unknown' || status === 'installing') && delay !== undefined) {
        retries++;
        timer = options.schedule(() => { timer = undefined; void check(); }, delay);
      } else active = false;
    }
    if (pending) { pending = false; void check(); }
  }
  function resume() {
    if (disposed || active || !options.visible()) return;
    active = true;
    retries = 0;
    void check();
  }
  return {
    resume,
    restart() { if (!disposed) { stop(); resume(); } },
    suspend: stop,
    dispose() { stop(); disposed = true; },
  };
}
"},{"path":"src/offline-readiness.ts","content":"export type OfflineStatus = "installing" | "ready" | "unavailable" | "unknown";

/** A completed precache marker and every recorded response are required evidence. */
export async function getOfflineStatus(
  storage: CacheStorage,
  scope: string,
  installing: boolean,
): Promise<OfflineStatus> {
  try {
    const prefix = "talksprout-scope-" + encodeURIComponent(scope) + "-";
    for (const name of (await storage.keys()).filter(name => name.startsWith(prefix))) {
      const cache = await storage.open(name);
      const marker = await cache.match(new URL("__offline_ready__", scope).href);
      if (!marker) continue;
      const urls: unknown = await marker.json();
      if (!Array.isArray(urls) || urls.length === 0 || !urls.every(url => typeof url === "string" && url.startsWith(scope))) continue;
      if ((await Promise.all(urls.map(url => cache.match(url)))).every(Boolean)) return "ready";
    }
    return installing ? "installing" : "unknown";
  } catch {
    return "unavailable";
  }
}
"},{"path":"src/useAppUpdate.ts","content":"import { useEffect, useRef, useState } from "react";
import { createAppUpdateManager, type AppUpdateSnapshot } from "./app-update";
import { getOfflineStatus, type OfflineStatus } from "./offline-readiness";
import { createOfflineCheck } from "./offline-check";
export type { OfflineStatus } from "./offline-readiness";
const completionKey = "talksprout:update-completed";
function consumeCompletion() {
  try {
    const time = Number(sessionStorage.getItem(completionKey));
    sessionStorage.removeItem(completionKey);
    return time > 0 && Date.now() - time >= 0 && Date.now() - time < 60000;
  } catch {
    return false;
  }
}
export function useAppUpdate() {
  const [snapshot, setSnapshot] = useState<AppUpdateSnapshot>({
    phase: "idle",
  });
  const [completed, setCompleted] = useState(consumeCompletion);
  const [offlineStatus, setOfflineStatus] = useState<OfflineStatus>("unknown");
  const manager = useRef<ReturnType<typeof createAppUpdateManager> | null>(
    null,
  );
  useEffect(() => {
    if (!("serviceWorker" in navigator) || !("caches" in window)) {
      setOfflineStatus("unavailable");
      return;
    }
    if (!import.meta.env.PROD) return;
    let disposed = false;
    let registration: ServiceWorkerRegistration | undefined;
    const offlineCheck = createOfflineCheck({
      read: () => getOfflineStatus(caches, registration!.scope, !!registration!.installing),
      publish: setOfflineStatus,
      visible: () => !!registration && document.visibilityState === "visible",
      schedule: (callback, delay) => setTimeout(callback, delay),
      cancel: (handle) => clearTimeout(handle),
    });
    const watched = new Set<ServiceWorker>();
    const observeWorker = () => {
      const worker = registration?.installing;
      if (worker && !watched.has(worker)) {
        watched.add(worker);
        worker.addEventListener("statechange", refreshOffline);
      }
      refreshOffline();
    };
    function refreshOffline() { offlineCheck.restart(); }
    const updates = createAppUpdateManager({
      container: navigator.serviceWorker,
      onChange: (next) => {
        setCompleted(false);
        setSnapshot(next);
      },
      onRegistrationError: () => {
        offlineCheck.suspend();
        if (!disposed) setOfflineStatus("unavailable");
      },
      onRegistration: (reg) => {
        if (disposed) return;
        registration = reg;
        reg.addEventListener("updatefound", observeWorker);
        observeWorker();
      },
      reload: () => {
        try {
          sessionStorage.setItem(completionKey, String(Date.now()));
        } catch {}
        location.reload();
      },
    });
    manager.current = updates;
    const resume = () => {
      if (document.visibilityState === "visible") {
        updates.resume(navigator.onLine);
        offlineCheck.resume();
      } else offlineCheck.suspend();
    };
    const reconnect = () => { offlineCheck.restart(); resume(); };
    document.addEventListener("visibilitychange", resume);
    window.addEventListener("pageshow", resume);
    window.addEventListener("online", reconnect);
    window.addEventListener("focus", resume);
    void updates.start(`${import.meta.env.BASE_URL}sw.js`);
    return () => {
      disposed = true;
      offlineCheck.dispose();
      registration?.removeEventListener("updatefound", observeWorker);
      for (const worker of watched) worker.removeEventListener("statechange", refreshOffline);
      updates.dispose();
      manager.current = null;
      document.removeEventListener("visibilitychange", resume);
      window.removeEventListener("pageshow", resume);
      window.removeEventListener("online", reconnect);
      window.removeEventListener("focus", resume);
    };
  }, []);
  useEffect(() => {
    if (!completed) return;
    const timer = setTimeout(() => setCompleted(false), 5000);
    return () => clearTimeout(timer);
  }, [completed]);
  return {
    snapshot,
    completed,
    offlineStatus,
    cacheUnavailable: offlineStatus === "unavailable",
    requestUpdate: () => manager.current?.request(),
  };
}
"},{"path":"vite.config.ts","content":"import react from "@vitejs/plugin-react";
import { defineConfig, type ResolvedConfig } from "vite";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { createHash } from "node:crypto";
let config: ResolvedConfig;
export default defineConfig({
  base: process.env.BASE_PATH || "./",
  plugins: [
    react(),
    {
      name: "offline-worker",
      configResolved(resolved) {
        config = resolved;
      },
      generateBundle(_, bundle) {
        const publicFiles = [
          "./recover.html",
          "./manifest.webmanifest",
          "./icons/icon.svg",
          "./icons/icon-192.png",
          "./icons/icon-512.png",
          "./icons/apple-touch-icon.png",
        ];
        const files = [
          "./",
          ...publicFiles,
          ...Object.keys(bundle).map((p) => "./" + p),
        ];
        const entries: [string, Uint8Array][] = [
          ...Object.entries(bundle).map(
            ([name, asset]): [string, Uint8Array] => {
              const source = asset.type === "chunk" ? asset.code : asset.source;
              return [
                "./" + name,
                typeof source === "string" ? Buffer.from(source) : source,
              ];
            },
          ),
          ...publicFiles.map((name): [string, Uint8Array] => [
            name,
            readFileSync(resolve(config.publicDir, name)),
          ]),
        ];
        const digest = createHash("sha256");
        for (const [name, bytes] of entries.sort(([a], [b]) =>
          a.localeCompare(b),
        )) {
          digest.update(JSON.stringify([name, bytes.byteLength]) + "\n");
          digest.update(bytes);
        }
        const version = digest.digest("hex").slice(0, 12);
        this.emitFile({
          type: "asset",
          fileName: "sw.js",
          source: `const PREFIX='talksprout-scope-'+encodeURIComponent(self.registration.scope)+'-';
const CACHE=PREFIX+'${version}';
const URLS=${JSON.stringify(files)};
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(async cache=>{await cache.addAll(URLS);await cache.put(new URL('__offline_ready__',self.registration.scope),new Response(JSON.stringify(URLS.map(url=>new URL(url,self.registration.scope).href))));})));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('message',event=>{if(event.data==='SKIP_WAITING')event.waitUntil(self.skipWaiting());});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(caches.open(CACHE).then(async cache=>{const cached=await cache.match(event.request,{ignoreSearch:true,ignoreVary:true});if(cached)return cached;try{return await fetch(event.request);}catch(error){if(event.request.mode==='navigate')return await cache.match(new URL('./',self.location.href));throw error;}}));});`,
        });
      },
    },
  ],
});
"}]

[{"path":"tests/shell.spec.ts","content":"import { test, expect, type Page, type Locator } from "@playwright/test";
import { prompts } from "../src/prompts";

const navigation = (page: Page) =>
  page.getByRole("navigation", { name: /^(主导航|Primary navigation)$/ });
const scrollRegion = (page: Page) => page.getByTestId("page-scroll");

async function box(locator: Locator) {
  const bounds = await locator.boundingBox();
  expect(bounds).not.toBeNull();
  return bounds!;
}

async function scrollToEnd(page: Page) {
  const region = scrollRegion(page);
  await region.evaluate((element) => {
    element.scrollTop = element.scrollHeight;
  });
  await expect
    .poll(() => region.evaluate((element) => element.scrollTop))
    .toBeGreaterThan(0);
  return region.evaluate((element) => element.scrollTop);
}

async function expectScroll(page: Page, position: number) {
  await expect
    .poll(async () =>
      Math.abs(
        (await scrollRegion(page).evaluate((element) => element.scrollTop)) -
          position,
      ),
    )
    .toBeLessThanOrEqual(2);
}

test("phone shell stays bounded while only its page region scrolls", async ({
  page,
}) => {
  await page.setViewportSize({ width: 320, height: 568 });
  await page.goto("/#review");
  await expect(page.locator(".card")).toHaveCount(4);
  const headerBefore = await box(page.locator(".app-header"));
  const navBefore = await box(navigation(page));
  await scrollToEnd(page);
  const headerAfter = await box(page.locator(".app-header"));
  const navAfter = await box(navigation(page));
  expect(Math.abs(headerAfter.y - headerBefore.y)).toBeLessThanOrEqual(1);
  expect(Math.abs(navAfter.y - navBefore.y)).toBeLessThanOrEqual(1);
  expect(navAfter.y + navAfter.height).toBeLessThanOrEqual(569);
  expect(navAfter.y).toBeGreaterThan(284);
  const region = await box(scrollRegion(page));
  expect(region.y).toBeGreaterThanOrEqual(
    headerAfter.y + headerAfter.height - 1,
  );
  expect(region.y + region.height).toBeLessThanOrEqual(navAfter.y + 1);
  expect(
    await page.evaluate(() => ({
      y: window.scrollY,
      width: document.documentElement.scrollWidth,
      height: document.documentElement.scrollHeight,
    })),
  ).toEqual({ y: 0, width: 320, height: 568 });
  const shell = await box(page.locator(".app-shell"));
  expect(shell.y).toBeGreaterThanOrEqual(-1);
  expect(shell.height).toBeLessThanOrEqual(569);
});

